ORD = {'first': 1, 'second': 2, 'third': 3, 'fourth': 4, 'fifth': 5, 'sixth': 6, 'seventh': 7, 'eighth': 8, 'ninth': 9, 'tenth': 10, 'eleventh': 11, 'twelfth': 12}
COSTE = {1: "La più corta e curva; vi passano sopra l'arteria e la vena succlavia. Inserzione dello scaleno anteriore e medio.",
         2: "Inserzione dello scaleno posteriore e del dentato anteriore; si articola con l'angolo sternale.",
         11: "Costa fluttuante: non raggiunge lo sterno né l'arcata costale.", 12: "Costa fluttuante, la più corta; inserzione del quadrato dei lombi."}
DENTI = {'medial incisor': 'incisivo centrale', 'lateral incisor': 'incisivo laterale', 'canine': 'canino', 'first premolar': 'primo premolare', 'second premolar': 'secondo premolare',
         'first molar tooth': 'primo molare', 'second molar tooth': 'secondo molare'}
VERT = {'C': ("cervicale", "Ha il forame trasversario, in cui passa l'arteria vertebrale (C1-C6), e il processo spinoso bifido."),
        'T': ("toracica", "Ha le faccette per le coste sul corpo e sui processi trasversi; il processo spinoso è lungo e inclinato verso il basso."),
        'L': ("lombare", "Corpo grande e reniforme, processi spinosi corti e orizzontali: porta il carico maggiore della colonna.")}

def ossa_serie(b):
    m = re.match(r'(\w+) rib$', b)
    if m:
        n = ORD[m.group(1).lower()]
        t = "vera: si unisce allo sterno con la propria cartilagine" if n <= 7 else "falsa: la cartilagine si unisce a quella della costa sopra (arcata costale)" if n <= 10 else "fluttuante"
        return f"{n}ª costa, costa {t}. " + COSTE.get(n, "Si articola dietro con le vertebre toraciche (testa e tubercolo).")
    m = re.match(r'Costal cartilage of (\w+) rib$', b)
    if m: return f"Cartilagine costale della {ORD[m.group(1)]}ª costa: rende elastica la gabbia toracica nella respirazione."
    m = re.match(r'Vertebra ([CTL])(\d+)$', b)
    if m:
        k, n = m.group(1), int(m.group(2)); s = VERT[k][1]
        if b == 'Vertebra C7': s = "Vertebra prominente: il processo spinoso lungo e non bifido si palpa alla base del collo."
        return f"{n}ª vertebra {VERT[k][0]}. " + s
    m = re.match(r'(First|Second|Third|Fourth|Fifth) (metacarpal|metatarsal) bone$', b)
    if m:
        n = ORD[m.group(1).lower()]; mano = m.group(2) == 'metacarpal'
        s = f"{n}° {'metacarpo' if mano else 'metatarso'}: base, corpo e testa. "
        if mano: s += "Il 1° (pollice) è il più corto e mobile." if n == 1 else "Le teste formano le nocche."
        else: s += "Il 1° (alluce) è il più robusto e porta molto carico." if n == 1 else "La tuberosità alla base riceve il peroneo breve; si frattura per trazione." if n == 5 else "Le teste appoggiano a terra nella fase di spinta."
        return s
    m = re.match(r'(Proximal|Middle|Distal) phalanx of (\w+) finger of (hand|foot)$', b)
    if m:
        p = {'Proximal': 'prossimale', 'Middle': 'media', 'Distal': 'distale'}[m.group(1)]; n = ORD[m.group(2)]
        dita = ['pollice', 'indice', 'medio', 'anulare', 'mignolo'] if m.group(3) == 'hand' else ['alluce', '2° dito', '3° dito', '4° dito', '5° dito']
        s = f"Falange {p} del {dita[n-1]}. "
        return s + ("Il pollice e l'alluce hanno solo due falangi." if n == 1 else "Ogni dito lungo ha tre falangi: prossimale, media e distale.")
    m = re.match(r'(Upper|Lower) (.+)$', b)
    if m and m.group(2) in DENTI:
        return f"Dente permanente: {DENTI[m.group(2)]} {'superiore' if m.group(1) == 'Upper' else 'inferiore'}. Corona, colletto e radice fissata nell'alveolo."
    return None

