# Muscoli in cui la fonte ha origine e inserzione scambiate (controllati sul modello confrontando le ossa delle aree).
SCAMBIO = ['pectoralis minor', 'serratus anterior', 'trapezius', 'scalenus anterior', 'scalenus medius', 'thyrohyoid', 'rectus abdominis',
           'rectus anterior capitis', 'rectus posterior major capitis', 'rectus posterior minor capitis', 'obliquus inferior capitis']
def correggi_aree(mus):
    for r in SCAMBIO:
        if r in mus: m = mus[r]; m['o'], m['e'] = m['e'], m['o']; m['fix'] = 1
    m = mus.get('pectoralis major')  # le aree del capo sternocostale stanno su sterno e coste: sono origini
    if m:
        st = [n for n in m['e'] if n.startswith('Sternocostal head')]
        if st: m['e'] = [n for n in m['e'] if n not in st]; m['o'] += st; m['fix'] = 1

def schede_muscoli(mus):
    # schede dei muscoli che non ne hanno una da schede.json (testi in schede2.py)
    import schede2
    for r, (ot, it, a, nv) in schede2.S.items():
        if r in mus and 'card' not in mus[r]: mus[r]['card'] = {'ot': ot, 'it': it, 'a': a, 'nv': nv}

# refusi nella traduzione italiana della Terminologia Anatomica 2 (TA2.csv)
REFUSI = {'quindo dito': 'quinto dito', 'Muscololi elevatore lunghi': 'Muscoli elevatori lunghi', 'elevatori breves': 'elevatori brevi',
          'spinale dellla': 'spinale della', 'dei muscol ': 'dei muscoli ', 'del osso': "dell'osso"}
def correggi_nomi(D):
    fix = lambda t: next((t.replace(a, b) for a, b in REFUSI.items() if a in t), t) if isinstance(t, str) else t
    for k, v in D['names'].items(): v[0] = fix(v[0])
    for m in D['mus'].values(): m['n'] = fix(m['n'])

def build(D):
    import collections
    B = lambda n: re.sub(r'\.(?:[oe]\d*[rl]|[rl]|[a-z])$', '', n)
    desc = {}
    for n, v in D['objs'].items():
        b = B(n)
        if b in desc: continue
        t = None
        if v[0] == 'ossa': t = OSSA.get(b) or ossa_serie(b)
        elif v[0] in ('encefalo', 'midollo'): t = ENCEFALO.get(b) or GRUPPI.get(v[2])
        elif v[0] == 'meningi': t = MENINGI.get(b) or GRUPPI.get(v[2])
        if t: desc[b] = t
    for l in D['lm']:
        if l[0] in REPERI: desc[l[0]] = REPERI[l[0]]
        elif l[0] in ENCEFALO: desc[l[0]] = ENCEFALO[l[0]]
    return desc

if __name__ == '__main__':
    D = json.load(open(sys.argv[1]))
    D['desc'] = build(D)
    correggi_nomi(D)
    json.dump(D, open(sys.argv[1], 'w'), ensure_ascii=False, separators=(',', ':'))
    lay = {}
    B = lambda n: re.sub(r'\.(?:[oe]\d*[rl]|[rl]|[a-z])$', '', n)
    for n, v in D['objs'].items():
        if v[0] in ('ossa', 'encefalo', 'meningi'):
            s = lay.setdefault(v[0], [set(), set()]); s[0].add(B(n)); (s[1].add(B(n)) if B(n) in D['desc'] else None)
    print({k: f'{len(v[1])}/{len(v[0])}' for k, v in lay.items()}, 'reperi', sum(1 for l in D['lm'] if l[0] in D['desc']), '/', len(D['lm']))
    miss = [k for k in REPERI if k not in {l[0] for l in D['lm']}]
    if miss: print('reperi non trovati:', miss)
